import React, { useState, useRef } from 'react';
import { FaPlaneDeparture, FaSearch } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const DepartureSelector = ({ onDepartureSelect, selectedDeparture }) => {
  const { theme } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState(null);
  const searchTimeoutRef = useRef(null);

  const searchLocation = async (query) => {
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }
    
    setIsSearching(true);
    setError(null);
    
    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=5&addressdetails=1`
      );
      
      if (!response.ok) {
        throw new Error('Failed to fetch location data');
      }
      
      const data = await response.json();
      setSearchResults(data);
    } catch (err) {
      setError('Error searching for location');
      console.error('Search error:', err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleSearchChange = (e) => {
    const query = e.target.value;
    setSearchQuery(query);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      searchLocation(query);
    }, 300);
  };

  const handleResultClick = (result) => {
    if (result.lat && result.lon) {
      const departure = {
        coordinates: [parseFloat(result.lat), parseFloat(result.lon)],
        name: result.display_name
      };
      onDepartureSelect(departure);
      setSearchQuery(result.display_name);
      setSearchResults([]);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center space-x-2">
        <FaPlaneDeparture style={{ color: theme.primary }} className="text-xl" />
        <h3 className="text-lg font-medium" style={{ color: theme.text }}>
          Departure Location
        </h3>
      </div>

      <div className="relative">
        <input
          type="text"
          value={searchQuery}
          onChange={handleSearchChange}
          placeholder="Where are you departing from?"
          className="w-full p-2 pl-10 border rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
          style={{ 
            borderColor: theme.border,
            backgroundColor: theme.background,
            color: theme.text,
            '::placeholder': {
              color: theme.textLight
            }
          }}
        />
        <FaSearch 
          className="absolute left-3 top-1/2 transform -translate-y-1/2"
          style={{ color: theme.textLight }}
        />
      </div>

      {isSearching && (
        <div className="text-sm" style={{ color: theme.textLight }}>
          Searching...
        </div>
      )}
      
      {error && (
        <div className="text-sm" style={{ color: theme.primary }}>
          {error}
        </div>
      )}
      
      {searchResults.length > 0 && (
        <div 
          className="absolute z-10 w-full mt-1 rounded-lg shadow-lg max-h-60 overflow-y-auto"
          style={{ 
            backgroundColor: theme.background,
            border: `1px solid ${theme.border}`
          }}
        >
          {searchResults.map((result) => (
            <button
              key={result.place_id}
              onClick={() => handleResultClick(result)}
              className="w-full px-4 py-2 text-left hover:bg-opacity-10 transition-colors"
              style={{ 
                color: theme.text,
                ':hover': {
                  backgroundColor: theme.primary
                }
              }}
            >
              {result.display_name}
            </button>
          ))}
        </div>
      )}

      {selectedDeparture && (
        <div 
          className="p-4 rounded-lg"
          style={{ 
            backgroundColor: theme.background,
            border: `1px solid ${theme.border}`
          }}
        >
          <div className="text-sm font-medium" style={{ color: theme.text }}>
            Selected Departure
          </div>
          <div className="text-sm" style={{ color: theme.textLight }}>
            {selectedDeparture.name}
          </div>
        </div>
      )}
    </div>
  );
};

export default DepartureSelector;
